package com.example.minimal

import android.app.Activity
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.os.Build
import android.os.Bundle
import android.view.Gravity
import android.widget.*

class MainActivity : Activity() {
    private var count = 0
        private var isDark = false

            override fun onCreate(savedInstanceState: Bundle?) {
                    super.onCreate(savedInstanceState)

                            val dp = resources.displayMetrics.density
                                    fun Int.dp(): Int = (this * dp).toInt()

                                            val root = LinearLayout(this).apply {
                                                        orientation = LinearLayout.VERTICAL
                                                                    setPadding(24.dp(), 48.dp(), 24.dp(), 24.dp())
                                                                                setBackgroundColor(Color.parseColor("#F5F7FA"))
                                                                                        }

                                                                                                val title = TextView(this).apply {
                                                                                                            text = "⚡ 極簡原生 Android UI"
                                                                                                                        textSize = 24f
                                                                                                                                    setTypeface(null, Typeface.BOLD)
                                                                                                                                                setTextColor(Color.parseColor("#1E293B"))
                                                                                                                                                        }
                                                                                                                                                                val subtitle = TextView(this).apply {
                                                                                                                                                                            text = "純網頁建立・GitHub 雲端直編・APK 小於 30KB"
                                                                                                                                                                                        textSize = 13f
                                                                                                                                                                                                    setTextColor(Color.parseColor("#64748B"))
                                                                                                                                                                                                                setPadding(0, 6.dp(), 0, 24.dp())
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                root.addView(title)
                                                                                                                                                                                                                                        root.addView(subtitle)

                                                                                                                                                                                                                                                fun createCard(): LinearLayout = LinearLayout(this).apply {
                                                                                                                                                                                                                                                            orientation = LinearLayout.VERTICAL
                                                                                                                                                                                                                                                                        setPadding(20.dp(), 20.dp(), 20.dp(), 20.dp())
                                                                                                                                                                                                                                                                                    background = GradientDrawable().apply {
                                                                                                                                                                                                                                                                                                    cornerRadius = 16.dp().toFloat()
                                                                                                                                                                                                                                                                                                                    setColor(Color.WHITE)
                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                            elevation = 4.dp().toFloat()
                                                                                                                                                                                                                                                                                                                                                        layoutParams = LinearLayout.LayoutParams(
                                                                                                                                                                                                                                                                                                                                                                        LinearLayout.LayoutParams.MATCH_PARENT,
                                                                                                                                                                                                                                                                                                                                                                                        LinearLayout.LayoutParams.WRAP_CONTENT
                                                                                                                                                                                                                                                                                                                                                                                                    ).apply { bottomMargin = 16.dp() }
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                    // 卡片 1：互動計數器
                                                                                                                                                                                                                                                                                                                                                                                                                            val counterCard = createCard()
                                                                                                                                                                                                                                                                                                                                                                                                                                    val countText = TextView(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                text = "點擊次數：0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                            textSize = 20f
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setTypeface(null, Typeface.BOLD)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setTextColor(Color.parseColor("#0F172A"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gravity = Gravity.CENTER
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setPadding(0, 0, 0, 12.dp())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val btnRow = LinearLayout(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        orientation = LinearLayout.HORIZONTAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gravity = Gravity.CENTER
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val addBtn = Button(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                text = "＋ 增加計數"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setOnClickListener {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            count++
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            countText.text = "點擊次數：$count"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val resetBtn = Button(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    text = "歸零"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setOnClickListener {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                count = 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                countText.text = "點擊次數：0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Toast.makeText(context, "已歸零", Toast.LENGTH_SHORT).show()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            btnRow.addView(addBtn)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    btnRow.addView(resetBtn)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            counterCard.addView(countText)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    counterCard.addView(btnRow)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            root.addView(counterCard)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 卡片 2：文字輸入與即時互動
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val inputCard = createCard()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val editText = EditText(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                hint = "輸入任意文字測試..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            isSingleLine = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val toastBtn = Button(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        text = "發送系統通知 (Toast)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setOnClickListener {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    val msg = editText.text.toString().ifBlank { "哈囉！這是雲端直編的原生 UI！" }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Toast.makeText(context, msg, Toast.LENGTH_SHORT).show()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                inputCard.addView(editText)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inputCard.addView(toastBtn)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                root.addView(inputCard)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 卡片 3：主題切換與設備資訊
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val infoCard = createCard()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val themeSwitch = Switch(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    text = "深色背景模式"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                textSize = 16f
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setOnCheckedChangeListener { _, isChecked ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            isDark = isChecked
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            root.setBackgroundColor(if (isDark) Color.parseColor("#0F172A") else Color.parseColor("#F5F7FA"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title.setTextColor(if (isDark) Color.WHITE else Color.parseColor("#1E293B"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            subtitle.setTextColor(if (isDark) Color.parseColor("#94A3B8") else Color.parseColor("#64748B"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        val sysInfo = TextView(this).apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    text = "\n📱 設備型號：${Build.MANUFACTURER} ${Build.MODEL}\n🤖 Android 版本：Android ${Build.VERSION.RELEASE} (API ${Build.VERSION.SDK_INT})"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                textSize = 13f
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setTextColor(Color.parseColor("#475569"))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            infoCard.addView(themeSwitch)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    infoCard.addView(sysInfo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            root.addView(infoCard)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setContentView(root)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        